            if is_sub and all(mul(a, a) in subset or len(subset)==1 for a in subset): # inverses check via closure usually enough for finite groups but let's be sure
                 pass # simplified check

    # Better way: generate subgroups from subsets of generators
    def gen_subgroup(generators):
        H = set([(1,1)])
        queue = list(generators)
        while queue:
            g = queue.pop(0)
            for h in list(H):
                new = mul(g, h)
                if new not in H:
                    H.add(new)
                    queue.append(new)
            # also powers of g
