def naive_kl(p, q):
    return p * np.log(p/q) + (1-p) * np.log((1-p)/(1-q))

def improved_kl(p, q):
    return p * np.log1p((p - q) / q) + (1-p) * np.log1p((q - p) / (1 - q))

