def rref(matrix):
    mat = [[Fraction(x) for x in row] for row in matrix]
    rows = len(mat)
    cols = len(mat[0]) if rows > 0 else 0
    lead = 0
    for r in range(rows):
        if lead >= cols:
            return mat
        i = r
        while mat[i][lead] == 0:
            i += 1
            if i == rows:
                i = r
                lead += 1
                if cols == lead:
                    return mat
        mat[i], mat[r] = mat[r], mat[i]
        lr = mat[r][lead]
        mat[r] = [x / lr for x in mat[r]]
        for i in range(rows):
            if i != r:
                lr = mat[i][lead]
                mat[i] = [mat[r][j] - lr * mat[r][j] for j in range(cols)]
        lead += 1
    return mat

